float new_step(float a, float b)
{
    if (a < b) return 1.;
    else return 0.;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord/iResolution.xy;

    float stripeNum = 10.;

    vec3 c0 = vec3(1, 0, 0);
    vec3 c1 = vec3(0, 1, 0);

    float stripe = new_step(mod(uv.x*stripeNum/2., 1.0), 0.5);

    vec3 c = vec3(stripe) * c0 + vec3(1. - stripe) * c1;

    fragColor = vec4(c, 1.);
}
